import { createPresenceChannel } from "./channel.js";
import { subscribeChannel } from "./subscription.js";

export function createPresencePanel(publish) {
  let release = () => {};
  return {
    show(channel, bootstrapMode = "synchronous") {
      release();

      let active = true;
      let unsubscribe = () => {};
      const stop = () => {
        active = false;
        unsubscribe();
      };

      // Own this visit before connect can synchronously publish and navigate.
      release = stop;
      const subscribedRelease = subscribeChannel(channel, bootstrapMode, (value) => {
        if (active) publish(value);
      });
      unsubscribe = subscribedRelease;

      // A synchronous publication may already have replaced or closed this visit.
      if (!active) subscribedRelease();
    },
    close() {
      release();
      release = () => {};
    },
  };
}

export async function renderPresence(token, bootstrapMode) {
  const events = [];
  const panel = createPresencePanel((value) => events.push(value));
  const channel = createPresenceChannel(token);
  panel.show(channel, bootstrapMode);
  await Promise.resolve();
  channel.emitUpdate();
  panel.close();
  return { events };
}

